use std::collections::HashSet;

fn has_common_element(a: &Vec<i32>, b: &Vec<i32>) -> bool {
    // To minimize work, build the HashSet from the smaller array
    if a.len() <= b.len() {
        let set: HashSet<i32> = a.iter().cloned().collect();
        for &val in b.iter() {
            if set.contains(&val) {
                return true;
            }
        }
    } else {
        let set: HashSet<i32> = b.iter().cloned().collect();
        for &val in a.iter() {
            if set.contains(&val) {
                return true;
            }
        }
    }
    false
}

